#!/usr/bin/env python3
# Cambia la barra azul por los servicios de HETNA CNC y agrega las traducciones
import os, re, json
BASE = os.environ.get("HETNA_SRC") or os.path.expanduser("~/hetnacnc/apps/storefront/src")
ok, falla = [], []


def paso(n, c):
    (ok if c else falla).append(n)


# 1) Encabezado: barra de servicios
hp = os.path.join(BASE, "components/hetna/HetnaHeader.tsx")
h = open(hp, encoding="utf-8").read()
if "ServiciosNav" not in h:
    h = h.replace(
        'import { SocialIcon } from "./SocialIcon"',
        'import { SocialIcon } from "./SocialIcon"\nimport { ServiciosNav } from "./ServiciosNav"',
        1,
    )
    h, n = re.subn(
        r"      \{/\* Categorias \*/\}\n      <nav.*?</nav>\n",
        "      {/* Tienda y servicios */}\n      <ServiciosNav categorias={navCategories} />\n",
        h,
        count=1,
        flags=re.S,
    )
    if n:
        open(hp, "w", encoding="utf-8").write(h)
h = open(hp, encoding="utf-8").read()
paso("barra de servicios", "<ServiciosNav categorias={navCategories} />" in h
     and 'import { ServiciosNav }' in h and 'aria-label="Categorías"' not in h)

