ep = os.path.join(BASE, "i18n/en.ts")
e = open(ep, encoding="utf-8").read()
ancla = "export const EN: Record<string, string> = {\n"
nuevas = "".join(
    " %s: %s,\n" % (json.dumps(k, ensure_ascii=False), json.dumps(v, ensure_ascii=False))
    for k, v in PARES.items()
    if json.dumps(k, ensure_ascii=False) + ":" not in e
)
if nuevas and ancla in e:
    e = e.replace(ancla, ancla + nuevas, 1)
    open(ep, "w", encoding="utf-8").write(e)
e = open(ep, encoding="utf-8").read()
paso("traducciones (%d)" % len(PARES), '"Laboratorio CAM":' in e and '"Cómo funciona":' in e)

